<?php
require "db.php";
$message='';$booking_id=(int)($_GET['booking_id']??$_POST['booking_id']??0);$pass=null;$payment_id=null;
if($_SERVER['REQUEST_METHOD']==='POST'){
  $bid=(int)$_POST['booking_id'];$method=$_POST['method'];
  $s=$conn->prepare("SELECT b.*,p.name passenger_name,p.email,f.flight_name,f.route,f.departure_date,f.departure_time,f.boarding_time,f.gate_no,f.travel_time,f.base_fare,a.airport_name FROM bookings b JOIN passengers p ON p.passenger_id=b.passenger_id JOIN flights f ON f.flight_id=b.flight_id LEFT JOIN airports a ON a.airport_id=b.airport_id WHERE b.booking_id=?");$s->bind_param('i',$bid);$s->execute();$pass=$s->get_result()->fetch_assoc();
  if(!$pass){$message='<div class="notice error">Booking not found.</div>';} else {
    $multipliers=['Economy'=>1,'Business'=>1.75,'First'=>2.5];$amount=(float)$pass['base_fare']*max(1,(int)$pass['passenger_count'])*($multipliers[$pass['travel_class']]??1);
    $s=$conn->prepare("INSERT INTO payments(booking_id,payment_date,amount,method) VALUES(?,CURDATE(),?,?)");$s->bind_param('ids',$bid,$amount,$method);
    if($s->execute()){$payment_id=$s->insert_id;$booking_id=$bid;$message='<div class="notice success">Payment successful. Your booking and boarding pass are ready.</div><script>window.addEventListener("load",()=>document.getElementById("thankYou").classList.add("show"));</script>';}else{$message='<div class="notice error">Payment failed. Please try again.</div>';}
  }
}
if($booking_id && !$pass){$s=$conn->prepare("SELECT b.*,p.name passenger_name,p.email,f.flight_name,f.route,f.departure_date,f.departure_time,f.boarding_time,f.gate_no,f.travel_time,f.base_fare,a.airport_name FROM bookings b JOIN passengers p ON p.passenger_id=b.passenger_id JOIN flights f ON f.flight_id=b.flight_id LEFT JOIN airports a ON a.airport_id=b.airport_id WHERE b.booking_id=?");$s->bind_param('i',$booking_id);$s->execute();$pass=$s->get_result()->fetch_assoc();}
$amount=0;if($pass){$multipliers=['Economy'=>1,'Business'=>1.75,'First'=>2.5];$amount=(float)$pass['base_fare']*max(1,(int)$pass['passenger_count'])*($multipliers[$pass['travel_class']]??1);}
?>
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Payment</title><link rel="stylesheet" href="style.css"></head><body><?php require "header.php"; ?><main class="container"><div class="page-head"><div class="eyebrow">Secure Checkout</div><h1>Payment & Boarding Pass</h1><p>Your booking ID and payment amount are generated from the booking. No manual amount entry is required.</p></div><?= $message ?>
<?php if($pass): ?><div class="checkout-grid"><div class="panel"><div class="invoice-head"><div><span class="eyebrow">Booking Bill</span><h2>FLY Air Booking</h2></div><span class="bill-id">FA-<?=str_pad($pass['booking_id'],6,'0',STR_PAD_LEFT)?></span></div><div class="bill-grid"><div><small>Passenger</small><strong><?=e($pass['passenger_name'])?></strong></div><div><small>Booking ID</small><strong>FA-<?=str_pad($pass['booking_id'],6,'0',STR_PAD_LEFT)?></strong></div><div><small>Flight</small><strong><?=e($pass['flight_name'])?></strong></div><div><small>Route</small><strong><?=e($pass['route'])?></strong></div><div><small>Travel time</small><strong><?=e($pass['travel_time']?:'—')?></strong></div><div><small>Seat</small><strong><?=e($pass['seat_number'])?></strong></div><div><small>Class</small><strong><?=e($pass['travel_class'])?></strong></div><div><small>Amount</small><strong>BDT <?=number_format($amount,2)?></strong></div></div><form method="post" class="payment-form"><input type="hidden" name="booking_id" value="<?=$pass['booking_id']?>"><div class="field"><label>Payment Method</label><div class="payment-methods"><label><input type="radio" name="method" value="Visa Card" required> Visa Card</label><label><input type="radio" name="method" value="MasterCard"> MasterCard</label><label><input type="radio" name="method" value="Debit Card"> Debit Card</label><label><input type="radio" name="method" value="Credit Card"> Credit Card</label><label><input type="radio" name="method" value="bKash"> bKash</label><label><input type="radio" name="method" value="PayPal"> PayPal</label></div></div><button class="btn btn-primary" type="submit">Pay BDT <?=number_format($amount,2)?> & Generate Boarding Pass</button></form></div>
<?php if($payment_id): ?><?php
  $flightCode='FL-'.str_pad($pass['flight_id'],5,'0',STR_PAD_LEFT);
  $barcodeValue=$flightCode.'|FA-'.str_pad($pass['booking_id'],6,'0',STR_PAD_LEFT).'|'.strtoupper($pass['seat_number']).'|'.strtoupper($pass['travel_class']);
  // Compact Code 128-B barcode generated locally, so no internet/CDN is required.
  $code128Patterns=[
    '212222','222122','222221','121223','121322','131222','122213','122312','132212','221213','221312','231212','112232','122132','122231','113222','123122','123221','223211','221132','221231','213212','223112','312131','311222','321122','321221','312212','322112','322211','212123','212321','232121','111323','131123','131321','112313','132113','132311','211313','231113','231311','112133','112331','132131','113123','113321','133121','313121','211331','231131','213113','213311','213131','311123','311321','331121','312131','312311','332111','314111','221411','431111','111224','111422','121124','121421','141122','141221','112214','112412','122114','122411','142112','142211','241211','221114','413111','241112','134111','111242','121142','121241','114212','124112','124211','411212','421112','421211','212141','214121','412121','111143','111341','131141','114113','114311','411113','411311','113141','114131','311141','411131','211412','211214','211232','2331112'
  ];
  $startCode=104; $checksum=$startCode; $barcodeCodes=[$startCode];
  $chars=str_split($barcodeValue);
  foreach($chars as $i=>$ch){ $v=ord($ch)-32; if($v<0 || $v>95) $v=0; $barcodeCodes[]=$v; $checksum += $v*($i+1); }
  $barcodeCodes[]=$checksum%103; $barcodeCodes[]=106;
  $x=8; $scale=2.2; $barcodeRects='';
  foreach($barcodeCodes as $code){ $pattern=$code128Patterns[$code]; $draw=true; for($j=0;$j<strlen($pattern);$j++){ $w=(int)$pattern[$j]*$scale; if($draw){ $barcodeRects .= '<rect x="'.round($x,2).'" y="0" width="'.round($w,2).'" height="72"/>'; } $x += $w; $draw=!$draw; } }
  $barcodeWidth=ceil($x+8);
?><div class="pass"><div class="pass-head"><strong>✈ FLY Air — Boarding Pass</strong><span>Payment: PY-<?=str_pad($payment_id,6,'0',STR_PAD_LEFT)?></span></div><div class="pass-body"><div class="pass-route"><?=e($pass['route'])?></div><div class="pass-grid"><div class="pass-item"><small>Passenger</small><b><?=e($pass['passenger_name'])?></b></div><div class="pass-item"><small>Flight ID</small><b><?=$flightCode?></b></div><div class="pass-item"><small>Flight</small><b><?=e($pass['flight_name'])?></b></div><div class="pass-item"><small>Date</small><b><?=e(date('d M Y',strtotime($pass['departure_date'])))?></b></div><div class="pass-item"><small>Departure</small><b><?=e(date('h:i A',strtotime($pass['departure_time'])))?></b></div><div class="pass-item"><small>Boarding</small><b><?=e(date('h:i A',strtotime($pass['boarding_time'])))?></b></div><div class="pass-item"><small>Class</small><b><?=e($pass['travel_class'])?></b></div><div class="pass-item"><small>Seat</small><b><?=e($pass['seat_number'])?></b></div><div class="pass-item"><small>Gate</small><b><?=e($pass['gate_no'])?></b></div><div class="pass-item"><small>Travel Time</small><b><?=e($pass['travel_time']?:'—')?></b></div></div><div class="boarding-barcode"><svg viewBox="0 0 <?=$barcodeWidth?> 92" role="img" aria-label="Boarding pass barcode"><rect x="0" y="0" width="<?=$barcodeWidth?>" height="72" fill="white"/><?=$barcodeRects?><text x="<?=($barcodeWidth/2)?>" y="88" text-anchor="middle" font-size="10" font-family="monospace" fill="black"><?=e($barcodeValue)?></text></svg></div><p class="no-print" style="margin-top:20px"><button class="btn btn-dark" onclick="window.print()">Print Boarding Pass</button></p></div></div><?php endif; ?></div><?php else: ?><div class="panel"><div class="notice info">Open Payment from a completed booking so the website can automatically load the registered passenger and booking bill.</div></div><?php endif; ?></main>
<div id="thankYou" class="modal"><div class="modal-card"><div class="success-icon">✓</div><h2>Thank you for your booking!</h2><p>Have a safe flight. Your payment and boarding pass have been generated successfully.</p><button class="btn btn-primary" onclick="document.getElementById('thankYou').classList.remove('show')">Continue</button></div></div>
